package com.walkthrough.api.transaction;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.JpaSpecificationExecutor;
import org.springframework.data.jpa.repository.Query;

import java.util.List;

/**
 * Read side of the transactions feature. One interface, three sources of methods:
 * <ul>
 *   <li>{@link JpaRepository} - CRUD, paging (generated by Spring)</li>
 *   <li>{@link JpaSpecificationExecutor} - {@code findAll(Specification, Pageable)}: dynamic WHERE clauses
 *       built from optional filters (see {@link TransactionSpecifications}) - like composing
 *       {@code qb.andWhere(...)} in Knex/TypeORM only when a filter is present</li>
 *   <li>{@link TransactionAnalyticsRepository} - our hand-written aggregate queries (custom fragment)</li>
 * </ul>
 */
public interface BankTransactionRepository extends JpaRepository<BankTransaction, Long>,
        JpaSpecificationExecutor<BankTransaction>, TransactionAnalyticsRepository {

    /** HQL functions year()/month() extract parts of a timestamp; used to build financial-year chips. */
    @Query("""
            select new com.walkthrough.api.transaction.MonthCount(
                year(t.transactedAt), month(t.transactedAt), count(t.id))
            from BankTransaction t
            group by year(t.transactedAt), month(t.transactedAt)
            """)
    List<MonthCount> countByMonth();
}
